+fn serialize_to_jsonl<T: Serialize>(records: &[T]) -> Result<Vec<u8>, AppError> {
+    let mut buf = Vec::new();
+    for record in records {
+        serde_json::to_writer(&mut buf, record).map_err(AppError::internal)?;
+        buf.push(b'\n');
+    }
+    Ok(buf)
