 221→+async fn create_export_job(
 222→+    State(state): State<Arc<AppState>>,
 223→+    Json(req): Json<ExportJobRequest>,
 224→+) -> Result<Json<ExportJobStatus>, AppError> {
 225→+    validate_dataset_name(&req.dataset)?;
 226→+    if !EXPORTABLE_DATASETS.contains(&req.dataset.as_str()) {
 227→+        return Err(AppError::bad_request(format!(
 228→+            "Dataset '{}' is not exportable. Exportable datasets: {}",
 229→+            req.dataset,
 230→+            EXPORTABLE_DATASETS.join(", ")
 231→+        )));
 232→+    }
 233→+
 234→+    let format_str = req.format.as_deref().unwrap_or("jsonl");
 235→+    let format: ExportFormat = format_str.parse().map_err(|_| {
 236→+        AppError::bad_request(format!(
 237→+            "Unsupported export format: {format_str}. Use 'jsonl' or 'csv'"
 238→+        ))
 239→+    })?;
 240→+
 241→+    validate_date_range(req.time_start, req.time_end)?;
 242→+
 243→+    let permit = state
 244→+        .job_semaphore
 245→+        .clone()
 246→+        .try_acquire_owned()
 247→+        .map_err(|_| AppError::service_unavailable("Too many concurrent jobs"))?;
 248→+
 249→+    state.prune_stale_export_jobs().await;
 250→+
 251→+    let job_id = Uuid::new_v4();
 252→+    let status = ExportJobStatus {
 253→+        id: job_id,
 254→+        state: JobState::Pending,
 255→+        dataset: req.dataset.clone(),
 256→+        format: format_str.to_string(),
 257→+        record_count: None,
 258→+        message: None,
 259→+    };
 260→+
 261→+    state.export_jobs.write().await.insert(
 262→+        job_id,
 263→+        ExportJobEntry {
 264→+            status: status.clone(),
 265→+            finished_at: None,
 266→+            data: None,
 267→+        },
 268→+    );
 269→+
 270→+    let state_clone = Arc::clone(&state);
 271→+    let dataset = req.dataset.clone();
 272→+    let target_id = req.target_id;
 273→+    let network = req.network.clone();
 274→+    let time_start = req.time_start;
 275→+    let time_end = req.time_end;
 276→+
 277→+    tokio::spawn(async move {
 278→+        let _permit = permit;
 279→+
 280→+        // Mark as running
 281→+        {
 282→+            let mut exports = state_clone.export_jobs.write().await;
 283→+            if let Some(entry) = exports.get_mut(&job_id) {
 284→+                entry.status.state = JobState::Running;
 285→+            }
 286→+        }
 287→+
 288→+        let result = run_export_job(
 289→+            &state_clone.repo,
 290→+            &dataset,
 291→+            format,
 292→+            target_id,
 293→+            network.as_deref(),
 294→+            time_start,
 295→+            time_end,
 296→+        )
 297→+        .await;
 298→+
 299→+        let mut exports = state_clone.export_jobs.write().await;
 300→+        if let Some(entry) = exports.get_mut(&job_id) {
 301→+            match result {
 302→+                Ok((body, record_count)) => {
 303→+                    entry.status.state = JobState::Completed;
 304→+                    entry.status.record_count = Some(record_count);
 305→+                    entry.status.message = Some(format!("Exported {record_count} records"));
 306→+                    entry.data = Some(ExportData {
 307→+                        content_type: content_type_for_format(format),
 308→+                        body,
 309→+                    });
 310→+                }
 311→+                Err(e) => {
 312→+                    entry.status.state = JobState::Failed;
 313→+                    entry.status.message = Some(format!("Export failed: {e}"));
 314→+                }
 315→+            }
 316→+            entry.finished_at = Some(Instant::now());
 317→+        }
 318→+    });
 319→+
 320→+    Ok(Json(status))
 321→+}
