 323→+async fn run_export_job(
 324→+    repo: &Repository,
 325→+    dataset: &str,
 326→+    format: ExportFormat,
 327→+    target_id: Option<Uuid>,
 328→+    network: Option<&str>,
 329→+    time_start: Option<i64>,
 330→+    time_end: Option<i64>,
 331→+) -> anyhow::Result<(Vec<u8>, usize)> {
 332→+    match dataset {
 333→+        "token_transfers" => {
 334→+            let records = repo
 335→+                .export_token_transfers(target_id, network, time_start, time_end)
 336→+                .await?;
 337→+            let count = records.len();
 338→+            let body = match format {
 339→+                ExportFormat::Jsonl => {
 340→+                    serialize_to_jsonl(&records).map_err(|e| anyhow::anyhow!("{}", e.message))?
 341→+                }
 342→+                ExportFormat::Csv => token_transfers_to_csv(&records),
 343→+            };
 344→+            Ok((body, count))
 345→+        }
 346→+        "native_balance_deltas" => {
 347→+            let records = repo
 348→+                .export_native_balance_deltas(target_id, network, time_start, time_end)
 349→+                .await?;
 350→+            let count = records.len();
 351→+            let body = match format {
 352→+                ExportFormat::Jsonl => {
 353→+                    serialize_to_jsonl(&records).map_err(|e| anyhow::anyhow!("{}", e.message))?
 354→+                }
 355→+                ExportFormat::Csv => native_balance_deltas_to_csv(&records),
 356→+            };
 357→+            Ok((body, count))
 358→+        }
 359→+        "decoded_events" => {
 360→+            let records = repo
 361→+                .export_decoded_events(target_id, network, time_start, time_end)
 362→+                .await?;
 363→+            let count = records.len();
 364→+            let body = match format {
 365→+                ExportFormat::Jsonl => {
 366→+                    serialize_to_jsonl(&records).map_err(|e| anyhow::anyhow!("{}", e.message))?
 367→+                }
 368→+                ExportFormat::Csv => decoded_events_to_csv(&records),
 369→+            };
 370→+            Ok((body, count))
 371→+        }
 372→+        "hl_fills" => {
 373→+            let records = repo
 374→+                .export_hl_fill_records(target_id, network, time_start, time_end)
 375→+                .await?;
 376→+            let count = records.len();
 377→+            let body = match format {
 378→+                ExportFormat::Jsonl => {
 379→+                    serialize_to_jsonl(&records).map_err(|e| anyhow::anyhow!("{}", e.message))?
 380→+                }
 381→+                ExportFormat::Csv => hl_fills_to_csv(&records),
 382→+            };
 383→+            Ok((body, count))
 384→+        }
 385→+        "hl_funding" => {
 386→+            let records = repo
 387→+                .export_hl_funding_payments(target_id, network, time_start, time_end)
 388→+                .await?;
 389→+            let count = records.len();
 390→+            let body = match format {
 391→+                ExportFormat::Jsonl => {
 392→+                    serialize_to_jsonl(&records).map_err(|e| anyhow::anyhow!("{}", e.message))?
 393→+                }
 394→+                ExportFormat::Csv => hl_funding_to_csv(&records),
 395→+            };
 396→+            Ok((body, count))
 397→+        }
 398→+        "positions" => {
 399→+            let records = repo
 400→+                .export_hl_position_changes(target_id, network, time_start, time_end)
 401→+                .await?;
 402→+            let count = records.len();
 403→+            let body = match format {
 404→+                ExportFormat::Jsonl => {
 405→+                    serialize_to_jsonl(&records).map_err(|e| anyhow::anyhow!("{}", e.message))?
 406→+                }
 407→+                ExportFormat::Csv => hl_positions_to_csv(&records),
 408→+            };
 409→+            Ok((body, count))
 410→+        }
 411→+        _ => Err(anyhow::anyhow!("Unknown dataset: {dataset}")),
 412→+    }
 413→+}
