 415→+async fn get_export_job_status(
 416→+    State(state): State<Arc<AppState>>,
 417→+    Path(job_id): Path<Uuid>,
 418→+) -> Result<Json<ExportJobStatus>, AppError> {
 419→+    let exports = state.export_jobs.read().await;
 420→+    match exports.get(&job_id) {
 421→+        Some(entry) => Ok(Json(entry.status.clone())),
 422→+        None => Err(AppError::not_found("Export job not found")),
 423→+    }
 424→+}
