 426→+async fn download_export(
 427→+    State(state): State<Arc<AppState>>,
 428→+    Path(job_id): Path<Uuid>,
 429→+) -> Result<Response, AppError> {
 430→+    let exports = state.export_jobs.read().await;
 431→+    let entry = exports
 432→+        .get(&job_id)
 433→+        .ok_or_else(|| AppError::not_found("Export job not found"))?;
 434→+
 435→+    match entry.status.state {
 436→+        JobState::Completed => {
 437→+            let data = entry
 438→+                .data
 439→+                .as_ref()
 440→+                .ok_or_else(|| AppError::internal("Export data missing"))?;
 441→+            let disposition = format!(
 442→+                "attachment; filename=\"{}-{}.{}\"",
 443→+                entry.status.dataset, job_id, entry.status.format,
 444→+            );
 445→+            Ok((
 446→+                StatusCode::OK,
 447→+                [
 448→+                    (axum::http::header::CONTENT_TYPE, data.content_type),
 449→+                    (
 450→+                        axum::http::header::CONTENT_DISPOSITION,
 451→+                        disposition.leak() as &str,
 452→+                    ),
 453→+                ],
 454→+                data.body.clone(),
 455→+            )
 456→+                .into_response())
 457→+        }
 458→+        JobState::Running | JobState::Pending => Err(AppError {
 459→+            status: StatusCode::CONFLICT,
 460→+            message: format!(
 461→+                "Export job {} is still {}",
 462→+                job_id,
 463→+                if matches!(entry.status.state, JobState::Running) {
 464→+                    "running"
 465→+                } else {
 466→+                    "pending"
 467→+                }
 468→+            ),
 469→+        }),
 470→+        JobState::Failed => Err(AppError::bad_request(format!(
 471→+            "Export job {} failed: {}",
 472→+            job_id,
 473→+            entry.status.message.as_deref().unwrap_or("unknown error")
 474→+        ))),
 475→+    }
 476→+}
